/* R01 arts courtyard: split existing terrain, preserve XYZ and all road/path surfaces. */
(function(root,factory){const api=factory();if(typeof module==='object')module.exports=api;else root.Brick84=api;})(this,()=>{
const polygon=[[40,496],[74,494],[82,485],[103,486],[125,475],[118,450],[109,438],[108,418],[105,393],[90,392],[79,400],[67,402],[54,413],[43,432],[40,451],[44,470]];
let masks=[],exclusions=[];
function prepare(triangulate,data){exclusions=[];for(const b of data.buildings){if(!b.p.some(p=>p[0]>30&&p[0]<135&&p[1]>385&&p[1]<510))continue;const pts=b.p.slice(),holes=[];for(const h of b.holes||[]){holes.push(pts.length);pts.push(...h);}const bi=triangulate(pts.flat(),holes);for(let i=0;i<bi.length;i+=3){const t=bi.slice(i,i+3).map(j=>pts[j]);if((t[1][0]-t[0][0])*(t[2][1]-t[0][1])-(t[1][1]-t[0][1])*(t[2][0]-t[0][0])<0)t.reverse();exclusions.push(t);}}const ix=triangulate(polygon.flat());masks=[];for(let i=0;i<ix.length;i+=3){const p=ix.slice(i,i+3).map(j=>polygon[j]);if((p[1][0]-p[0][0])*(p[2][1]-p[0][1])-(p[1][1]-p[0][1])*(p[2][0]-p[0][0])<0)p.reverse();masks.push(p);}}
function cut(vs,a,b){const d=v=>(b[0]-a[0])*(v[2]-a[1])-(b[1]-a[1])*(v[0]-a[0]),pos=[],neg=[];for(let i=0;i<vs.length;i++){const p=vs[i],q=vs[(i+1)%vs.length],dp=d(p),dq=d(q);if(dp>=0)pos.push(p);if(dp<=0)neg.push(p);if((dp<0&&dq>0)||(dp>0&&dq<0)){const t=dp/(dp-dq),r=p.map((x,j)=>x+(q[j]-x)*t);pos.push(r);neg.push(r);}}return[pos,neg];}
function split(vs,mask){let inner=vs,out=[];for(let k=0;k<3&&inner.length>=3;k++){const[a,b]=cut(inner,mask[k],mask[(k+1)%3]);if(b.length>=3)out.push(b);inner=a;}return{inner,out};}
const overlaps=p=>!(p.every(v=>v[0]<40)||p.every(v=>v[0]>125)||p.every(v=>v[2]<392)||p.every(v=>v[2]>496));
function partition(pos,indices,kind){if(!['grass','planting'].includes(kind)||!masks.length)return[{pos,indices,kind}];let hit=false;for(let j=0;j<pos.length;j+=3)if(pos[j]>=40&&pos[j]<=125&&pos[j+2]>=392&&pos[j+2]<=496){hit=true;break;}if(!hit)return[{pos,indices,kind}];
const retained={pos:[],indices:[],kind},brick={pos:[],indices:[],kind:'brick84'};
function put(g,p){for(let j=1;j<p.length-1;j++){const a=p[0],b=p[j],c=p[j+1];if(Math.abs((b[0]-a[0])*(c[2]-a[2])-(b[2]-a[2])*(c[0]-a[0]))<1e-10)continue;const n=g.pos.length/3;g.pos.push(...a,...b,...c);g.indices.push(n,n+1,n+2);}}
for(let i=0;i<indices.length;i+=3){const tri=Array.from(indices.slice(i,i+3),j=>Array.from(pos.slice(j*3,j*3+3)));if(!overlaps(tri)){put(retained,tri);continue;}let rest=[tri];for(const mask of masks){const next=[];for(const p of rest){const q=split(p,mask);if(q.inner.length>=3){let parts=[q.inner];for(const hole of exclusions){const next=[];for(const part of parts){if(part.every(v=>v[0]<Math.min(...hole.map(p=>p[0])))||part.every(v=>v[0]>Math.max(...hole.map(p=>p[0])))||part.every(v=>v[2]<Math.min(...hole.map(p=>p[1])))||part.every(v=>v[2]>Math.max(...hole.map(p=>p[1])))){next.push(part);continue;}const h=split(part,hole);if(h.inner.length>=3)put(retained,h.inner);next.push(...h.out);}parts=next;}for(const part of parts)put(brick,part);}next.push(...q.out);}rest=next;}for(const p of rest)put(retained,p);}
return brick.indices.length?[retained,brick].filter(p=>p.indices.length):[{pos,indices,kind}];}
function material(B,scene){const m=new B.StandardMaterial('arts-brick84',scene),t=new B.DynamicTexture('brick84-4m',512,scene,true),c=t.getContext();c.fillStyle='#aa8777';c.fillRect(0,0,512,512);const colors=['#a96c57','#ae725c','#ac705b','#b07560','#aa6d58'];for(let y=0;y<16;y++)for(let x=-1;x<9;x++){c.fillStyle=colors[((y*11+x*7)%5+5)%5];c.fillRect(x*64+(y%2)*32+1,y*32+1,62,30);}t.update();t.wrapU=t.wrapV=B.Texture.WRAP_ADDRESSMODE;t.anisotropicFilteringLevel=8;m.diffuseTexture=t;m.specularColor=B.Color3.Black();return m;}
return{prepare,partition,material,polygon};
});
